  quantumProcessingTextbookParse_s1: "// GENERATED by src/scripts/leanDerived.ts from Qpu/General/Textbook.lean. Do not edit: the Lean file is the author.",
  quantumProcessingTextbookParse_says2: "⟦0⟧ textbook theorem(s) read from the Lean file",
