/** Every sentence the tree says, by the name Lean gives it. */
export const PROSE: { readonly [K in keyof typeof SENTENCES]: string } = SENTENCES
/** A sentence with its computed values: the nth value goes where the sentence says `⟦n⟧`. */
export const proseFill = (text: string, ...values: unknown[]): string => text.replace(/⟦(\d+)⟧/g, (_, i) => String(values[Number(i)]))
